package com.app.entity;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="society_shift_handovers") @Data @Builder @NoArgsConstructor @AllArgsConstructor
public class SocietyShiftHandover {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="account_id",nullable=false) private Account account; @Column(nullable=false) private LocalDate shiftDate; @Column(nullable=false,length=100) private String shiftName; @Column(length=3000) private String openItems; @Column(length=2000) private String incidents; @Column(length=2000) private String expectedVisitors; @Column(length=2000) private String assetsHandedOver; @Column(length=2000) private String equipmentStatus; @Column(length=1000) private String attendanceShortages; @Column(length=2000) private String notes; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="sender_user_id",nullable=false) private User sender; private String receiverName; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="receiver_user_id") private User receiver; private LocalDateTime acknowledgedAt; @Column(nullable=false,updatable=false) @Builder.Default private LocalDateTime createdAt=LocalDateTime.now();}
